@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

abstract class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

Person "1" -- "0..*" ResearchInstitution : works for

Person "0..1" -- "0..*" PeerReviewedPaper : reviews
Person "1" -- "0..*" ScientificArticle : authors

ScientificArticle "1" *-- "1..*" AuthorPosition
AuthorPosition "1" -- "1" Person

PeerReviewedPaper "0..*" -- "0..*" Person : reviewed by

TechnicalReport "0..*" -- "1" ResearchInstitution : published by

Publisher "1" -- "1..*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes to

PeerReviewedPaper "0..*" -- "0..1" Journal : published in

@enduml

